    /**
     * Tests getting all Channels.
     *
     * @return    Collection
     */
    public List<Channel> testGetAll() throws Throwable {
    LOGGER.info( "ChannelTest:testGetAll() - Retrieving Collection of Channels:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Channel : " );
    List<Channel> collection  = null;

    try {
        // call the static get method on the ChannelService
        collection = service.getAllChannel();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Channel currEntity  = null;
            Iterator<Channel> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getChannelId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

